export const trustedPluginScript=`const client=window.GenPluginUI;window.client=client;window.__lastFlush='';addEventListener('message',event=>{if(event.data?.type==='gen.plugin.flush')window.__lastFlush=event.data.id;});let started=false;const activate=()=>{if(!started&&client.isPluginActive()){started=true;client.pluginReady();void client.pluginRequest('state.read',{key:'initial'}).then(value=>{document.getElementById('result').textContent=value.private;});}};client.onPluginVisibility(activate);activate();`;
